self.KB_CONTENT["card:792947"]={"id":"card:792947","ty":"card","sourceId":"792947","title":"『信用狀變更建立作業』中的『結案碼 (TJ019)』為何？","ver":"GP4以上","topic":"結案","keywords":["結案","信用"],"y":"other","answer":"* 本信用狀已否結案之判斷碼。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
