self.KB_CONTENT["card:757698"]={"id":"card:757698","ty":"card","sourceId":"757698","title":"『採購變更單建立作業』中的『簽核狀態 (TE025)』為何？","ver":"iGP","topic":"變更單","keywords":["變更單","採購","狀態","電子"],"y":"other","answer":"* 此欄位僅作顯示.簽核狀態類型區分為0.待處理、1.簽核中、2.退件、3.已核准、4.取消確認中、5.作廢中、6.取消作廢中及N.不執行電子簽核。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
